    M_sub = Mk(:, 1:end-1);
    rhs = zeros(k + 1, 1);
    rhs(1) = 1;                       % R_k[x] 中首项 x^k 的系数为 1
    coeffs_no_const = M_sub \ rhs;
    p_k = [coeffs_no_const; 0]';      % 行向量，适配 polyval
    fprintf('k = %d, p_k 系数 (降幂): ', k);
    disp(p_k);

